//! Owner-only surface. Editing the payment-token allowlist is the owner's *only* power:
//! there is no admin path to move funds, reassign invoices or change amounts.

use near_sdk::{AccountId, near};

// `ContractExt` is generated by `#[near(contract_state)]` and required by any
// `#[near] impl Contract` block outside lib.rs.
use crate::errors::{E_TOKEN_ALREADY_ALLOWED, E_TOKEN_NOT_ALLOWED};
use crate::{Contract, ContractExt};
use near_sdk::env;

#[near]
impl Contract {
    pub fn add_allowed_token(&mut self, token: AccountId) {
        self.assert_owner();
        if !self.allowed_tokens.insert(token) {
            env::panic_str(E_TOKEN_ALREADY_ALLOWED);
        }
    }

    /// Removing a token stops new invoices being denominated in it. Invoices that already
    /// reference it keep working, so removal can never strand money mid-payment.
    pub fn remove_allowed_token(&mut self, token: AccountId) {
        self.assert_owner();
        if !self.allowed_tokens.remove(&token) {
            env::panic_str(E_TOKEN_NOT_ALLOWED);
        }
    }

    pub fn get_allowed_tokens(&self) -> Vec<AccountId> {
        self.allowed_tokens.iter().cloned().collect()
    }

    pub fn is_token_allowed(&self, token: AccountId) -> bool {
        self.allowed_tokens.contains(&token)
    }
}

#[cfg(test)]
mod tests {
    use crate::test_utils::*;

    #[test]
    fn init_allowlist_is_readable() {
        let contract = setup(OWNER);
        assert_eq!(contract.get_allowed_tokens(), vec![acc(USDC)]);
        assert!(contract.is_token_allowed(acc(USDC)));
        assert!(!contract.is_token_allowed(acc(OTHER_TOKEN)));
    }

    #[test]
    fn owner_can_add_and_remove() {
        let mut contract = setup(OWNER);

        contract.add_allowed_token(acc(OTHER_TOKEN));
        assert!(contract.is_token_allowed(acc(OTHER_TOKEN)));

        contract.remove_allowed_token(acc(OTHER_TOKEN));
        assert!(!contract.is_token_allowed(acc(OTHER_TOKEN)));
        // Removing one token leaves the others alone.
        assert!(contract.is_token_allowed(acc(USDC)));
    }

    #[test]
    #[should_panic(expected = "E_NOT_OWNER")]
    fn stranger_cannot_add() {
        let mut contract = setup(STRANGER);
        contract.add_allowed_token(acc(OTHER_TOKEN));
    }

    #[test]
    #[should_panic(expected = "E_NOT_OWNER")]
    fn stranger_cannot_remove() {
        let mut contract = setup(STRANGER);
        contract.remove_allowed_token(acc(USDC));
    }

    #[test]
    #[should_panic(expected = "E_NOT_OWNER")]
    fn issuer_is_not_owner() {
        let mut contract = setup(ISSUER);
        contract.add_allowed_token(acc(OTHER_TOKEN));
    }

    #[test]
    #[should_panic(expected = "E_TOKEN_ALREADY_ALLOWED")]
    fn adding_twice_panics() {
        let mut contract = setup(OWNER);
        contract.add_allowed_token(acc(USDC));
    }

    #[test]
    #[should_panic(expected = "E_TOKEN_NOT_ALLOWED")]
    fn removing_absent_panics() {
        let mut contract = setup(OWNER);
        contract.remove_allowed_token(acc(OTHER_TOKEN));
    }
}
